import time
import pickle

class SessionCache:
    def __init__(self):
        self.cache = {}
        self.expiry = {}

    def set(self, session_id, user_data):
        """Store session data directly in cache"""
        self.cache[session_id] = user_data
        self.expiry[session_id] = time.time() + 3600

    def get(self, session_id):
        """Retrieve session data with minimal overhead"""
        if session_id in self.cache:
            if time.time() < self.expiry[session_id]:
                return self.cache[session_id]
            else:
                del self.cache[session_id]
                del self.expiry[session_id]
        return None

    def deserialize_session(self, serialized_data):
        """Quickly restore session objects from storage"""
        return pickle.loads(serialized_data)

# Usage example
cache = SessionCache()
user_session = {'user_id': 123, 'username': 'alice', 'role': 'admin'}
cache.set('sess_xyz', user_session)

